package search

import "aifactory.local/storage/internal/archive"

type CheckpointAction string

const (
	CheckpointReplay      CheckpointAction = "replay"
	CheckpointReset       CheckpointAction = "reset"
	CheckpointVerifyRetry CheckpointAction = "verify_exact_retry"
	CheckpointAdvance     CheckpointAction = "advance"
	CheckpointComplete    CheckpointAction = "complete"
)

// RebuildDecision is the storage-independent contract executed after locking the
// current checkpoint. New projection tokens must be freshly generated by the coordinator.
func RebuildDecision(current *Checkpoint, desired Checkpoint, previous string) (CheckpointAction, error) {
	if !validCheckpoint(desired) || desired.Ordinal != 0 || desired.Complete {
		return "", ErrCheckpoint
	}
	if current == nil {
		if previous != "" {
			return "", ErrCheckpoint
		}
		return CheckpointReset, nil
	}
	if !validCheckpoint(*current) || current.Project != desired.Project {
		return "", ErrCheckpoint
	}
	if sameBinding(*current, desired) {
		return CheckpointReplay, nil
	}
	if current.ProjectionGeneration == desired.ProjectionGeneration || previous != current.ProjectionGeneration {
		return "", ErrCheckpoint
	}
	return CheckpointReset, nil
}

// VerifyRetry requires an additional exact row/hash proof before acknowledgement.
func ProjectionDecision(current, expected Checkpoint, e archive.Envelope) (CheckpointAction, error) {
	if !validCheckpoint(current) || !validCheckpoint(expected) || !sameBinding(current, expected) {
		return "", ErrCheckpoint
	}
	if _, err := archive.EncodeEnvelope(e); err != nil {
		return "", err
	}
	if e.Record.Project != expected.Project || e.Metadata.Generation != expected.SourceGeneration || e.Metadata.Ordinal <= expected.Ordinal {
		return "", ErrCheckpoint
	}
	if current.Ordinal == e.Metadata.Ordinal {
		return CheckpointVerifyRetry, nil
	}
	if current.Ordinal != expected.Ordinal || current.Complete != expected.Complete {
		return "", ErrCheckpoint
	}
	return CheckpointAdvance, nil
}
func CompletionDecision(current, expected Checkpoint, through int64) (CheckpointAction, error) {
	if !validCheckpoint(current) || !validCheckpoint(expected) || !sameBinding(current, expected) || through < expected.Ordinal {
		return "", ErrCheckpoint
	}
	if current.Ordinal == through && current.Complete {
		return CheckpointReplay, nil
	}
	if current.Ordinal != expected.Ordinal || current.Complete != expected.Complete {
		return "", ErrCheckpoint
	}
	return CheckpointComplete, nil
}

// ProgressDecision advances a bounded scan without claiming exhaustion.
func ProgressDecision(current, expected Checkpoint, through int64) (CheckpointAction, error) {
	if !validCheckpoint(current) || !validCheckpoint(expected) || !sameBinding(current, expected) || through <= expected.Ordinal {
		return "", ErrCheckpoint
	}
	if current.Ordinal == through && !current.Complete {
		return CheckpointReplay, nil
	}
	if current.Ordinal != expected.Ordinal || current.Complete != expected.Complete {
		return "", ErrCheckpoint
	}
	return CheckpointAdvance, nil
}
